  if (csLabel && !csLabel.querySelector('.cds-choiceInput-checked')) {
    csLabel.click();
  }

  // Level: Beginner
  const begLabel = labels.find(l => l.textContent?.trim().startsWith("Beginner("));
  if (begLabel && !begLabel.querySelector('.cds-choiceInput-checked')) {
    begLabel.click();
  }

  // Learning Product: Courses
  const courseLabel = labels.find(l => l.textContent?.trim().startsWith("Courses("));
  if (courseLabel && !courseLabel.querySelector('.cds-choiceInput-checked')) {
    courseLabel.click();
  }

