const tabId = 1854033397;
// In the current dialog, let's select:
// 1. Skill: Advertising
// 2. Topic: Computer Science
// 3. Level: Beginner
// 4. Learning Product: Courses

const selectFilters = await browserjs(tabId, () => {
  const dialog = document.querySelector('div.cds-Dialog-dialog');
  if (!dialog) return "Dialog not found";

  // Find Skill: Advertising
  const labels = Array.from(dialog.querySelectorAll('label.cds-checkboxAndRadio-label'));
  const adLabel = labels.find(l => l.textContent?.trim().startsWith("Advertising("));
  if (adLabel && !adLabel.querySelector('.cds-choiceInput-checked')) {
    adLabel.click();
  }

  // Topic: Computer Science
  const csLabel = labels.find(l => l.textContent?.trim().startsWith("Computer Science("));
  if (csLabel && !csLabel.querySelector('.cds-choiceInput-checked')) {
    csLabel.click();
  }

  // Level: Beginner
  const begLabel = labels.find(l => l.textContent?.trim().startsWith("Beginner("));
  if (begLabel && !begLabel.querySelector('.cds-choiceInput-checked')) {
    begLabel.click();
  }

  // Learning Product: Courses
  const courseLabel = labels.find(l => l.textContent?.trim().startsWith("Courses("));
  if (courseLabel && !courseLabel.querySelector('.cds-choiceInput-checked')) {
    courseLabel.click();
  }

  return {
    adLabel: adLabel?.textContent?.trim(),
    csLabel: csLabel?.textContent?.trim(),
    begLabel: begLabel?.textContent?.trim(),
    courseLabel: courseLabel?.textContent?.trim()
  };
});
console.log("Selected:", selectFilters);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1500 });

