const fullSkills = await browserjs(tabId, () => {
  const showMoreBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent?.includes("Show all") || b.textContent?.includes("skills"));
  if (showMoreBtn) showMoreBtn.click();

  const skillElements = Array.from(document.querySelectorAll('ul li, div[data-testid*="skill"], .cds-119')).map(e => e.textContent?.trim());
  return {
    title: document.querySelector('h1')?.textContent?.trim(),
    provider: document.querySelector('h3, [data-e2e="course-partner-name"], [class*="partner"]')?.textContent?.trim(),
    breadcrumbs: Array.from(document.querySelectorAll('nav[aria-label*="breadcrumb"] a, a[href*="/browse/"]')).map(a => a.textContent?.trim()),
    text: document.body.innerText
  };
});

// Let's find the Skills you'll gain section in text
const text = fullSkills.text;
const skillIndex = text.indexOf("Skills you'll gain");
if (skillIndex !== -1) {
  console.log(text.slice(skillIndex, skillIndex + 500));
} else {
  console.log("Could not find Skills you'll gain directly");
}

console.log("Breadcrumbs / Categories:", fullSkills.breadcrumbs);

